import unittest
from app import greet

class GreetingTests(unittest.TestCase):
    def test_names(self):
        self.assertEqual(greet(" Eterna "), "안녕하세요, Eterna님!")
        self.assertEqual(greet(" "), "안녕하세요, 친구님!")
